import React, { useState } from 'react';
import { Link, useLocation } from 'react-router-dom';
import { motion, AnimatePresence } from 'framer-motion';
import { Menu, X } from 'lucide-react';

const Logo = () => (
  <svg width="44" height="44" viewBox="0 0 44 44" fill="none" xmlns="http://www.w3.org/2000/svg">
    <defs>
      <radialGradient id="glow" cx="50%" cy="50%" r="50%">
        <stop offset="0%" stopColor="#D6BE8A" stopOpacity="0.4" />
        <stop offset="100%" stopColor="#DDB7B0" stopOpacity="0" />
      </radialGradient>
    </defs>
    <circle cx="22" cy="22" r="21" fill="url(#glow)" />
    {/* Heart */}
    <path d="M22 32 C22 32 10 24 10 17 C10 13.5 12.5 11 16 11 C18.5 11 20.5 12.5 22 14.5 C23.5 12.5 25.5 11 28 11 C31.5 11 34 13.5 34 17 C34 24 22 32 22 32Z"
      fill="none" stroke="#DDB7B0" strokeWidth="1.2" strokeLinejoin="round" />
    {/* Keyhole */}
    <circle cx="22" cy="20" r="3" fill="none" stroke="#D6BE8A" strokeWidth="1.1" />
    <rect x="20.5" y="22.5" width="3" height="4" rx="1" fill="none" stroke="#D6BE8A" strokeWidth="1.1" />
    {/* Wings */}
    <path d="M10 20 Q6 17 8 13 Q12 15 12 20" fill="none" stroke="#B8C4B2" strokeWidth="1" strokeLinecap="round" />
    <path d="M34 20 Q38 17 36 13 Q32 15 32 20" fill="none" stroke="#B8C4B2" strokeWidth="1" strokeLinecap="round" />
    {/* Feather accent */}
    <path d="M8 13 Q10 11 12 13" fill="none" stroke="#B8C4B2" strokeWidth="0.8" strokeLinecap="round" />
    <path d="M36 13 Q34 11 32 13" fill="none" stroke="#B8C4B2" strokeWidth="0.8" strokeLinecap="round" />
  </svg>
);

const navLinks = [
  { label: 'Home', path: '/' },
  { label: 'About', path: '/about' },
  { label: 'Services', path: '/services' },
  { label: 'Blog', path: '/blog' },
  { label: 'Contact', path: '/contact' },
];

const Navbar = ({ scrolled }) => {
  const [open, setOpen] = useState(false);
  const location = useLocation();

  return (
    <motion.nav
      initial={{ y: -60, opacity: 0 }}
      animate={{ y: 0, opacity: 1 }}
      transition={{ duration: 0.8, ease: 'easeOut' }}
      style={{
        position: 'fixed',
        top: 0,
        left: 0,
        right: 0,
        zIndex: 100,
        padding: '0 2rem',
        height: '72px',
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'space-between',
        background: scrolled ? 'rgba(250,246,242,0.92)' : 'transparent',
        backdropFilter: scrolled ? 'blur(20px)' : 'none',
        borderBottom: scrolled ? '1px solid rgba(221,183,176,0.2)' : 'none',
        transition: 'all 0.4s ease',
      }}
    >
      {/* Logo */}
      <Link to="/" style={{ display: 'flex', alignItems: 'center', gap: '10px' }}>
        <Logo />
        <div>
          <div style={{ fontFamily: 'Cormorant Garamond, serif', fontSize: '1.25rem', fontWeight: 600, color: '#3D2B38', lineHeight: 1 }}>
            Struvive
          </div>
          <div style={{ fontFamily: 'Manrope, sans-serif', fontSize: '0.62rem', letterSpacing: '0.18em', color: '#B8C4B2', textTransform: 'uppercase', marginTop: '1px' }}>
            Emolings
          </div>
        </div>
      </Link>

      {/* Desktop Nav */}
      <div style={{ display: 'flex', alignItems: 'center', gap: '2.2rem' }} className="desktop-nav">
        {navLinks.map(link => (
          <Link
            key={link.path}
            to={link.path}
            style={{
              fontFamily: 'Manrope, sans-serif',
              fontSize: '0.85rem',
              fontWeight: 500,
              color: location.pathname === link.path ? '#DDB7B0' : '#6E5563',
              letterSpacing: '0.04em',
              transition: 'color 0.3s',
              position: 'relative',
              paddingBottom: '2px',
            }}
          >
            {link.label}
            {location.pathname === link.path && (
              <motion.div
                layoutId="underline"
                style={{ position: 'absolute', bottom: -2, left: 0, right: 0, height: '1px', background: '#DDB7B0' }}
              />
            )}
          </Link>
        ))}
        <Link to="/book">
          <motion.button
            whileHover={{ scale: 1.04, boxShadow: '0 4px 24px rgba(221,183,176,0.45)' }}
            whileTap={{ scale: 0.97 }}
            style={{
              background: 'linear-gradient(135deg, #DDB7B0, #D6BE8A)',
              color: '#FFFDFC',
              border: 'none',
              borderRadius: '50px',
              padding: '10px 24px',
              fontFamily: 'Manrope, sans-serif',
              fontSize: '0.82rem',
              fontWeight: 600,
              letterSpacing: '0.04em',
              cursor: 'pointer',
              boxShadow: '0 2px 14px rgba(221,183,176,0.3)',
            }}
          >
            Book Session
          </motion.button>
        </Link>
      </div>

      {/* Mobile Menu Button */}
      <button
        onClick={() => setOpen(!open)}
        style={{ display: 'none', background: 'none', border: 'none', color: '#6E5563', cursor: 'pointer' }}
        className="mobile-menu-btn"
      >
        {open ? <X size={22} /> : <Menu size={22} />}
      </button>

      {/* Mobile Menu */}
      <AnimatePresence>
        {open && (
          <motion.div
            initial={{ opacity: 0, y: -20 }}
            animate={{ opacity: 1, y: 0 }}
            exit={{ opacity: 0, y: -20 }}
            style={{
              position: 'absolute',
              top: '72px',
              left: 0,
              right: 0,
              background: 'rgba(250,246,242,0.97)',
              backdropFilter: 'blur(20px)',
              padding: '1.5rem 2rem 2rem',
              borderBottom: '1px solid rgba(221,183,176,0.2)',
              display: 'flex',
              flexDirection: 'column',
              gap: '1.2rem',
            }}
          >
            {navLinks.map(link => (
              <Link
                key={link.path}
                to={link.path}
                onClick={() => setOpen(false)}
                style={{
                  fontFamily: 'Manrope, sans-serif',
                  fontSize: '1rem',
                  fontWeight: 500,
                  color: location.pathname === link.path ? '#DDB7B0' : '#6E5563',
                }}
              >
                {link.label}
              </Link>
            ))}
            <Link to="/book" onClick={() => setOpen(false)}>
              <button style={{
                background: 'linear-gradient(135deg, #DDB7B0, #D6BE8A)',
                color: '#FFFDFC',
                border: 'none',
                borderRadius: '50px',
                padding: '12px 28px',
                fontFamily: 'Manrope, sans-serif',
                fontSize: '0.9rem',
                fontWeight: 600,
                cursor: 'pointer',
                width: '100%',
              }}>
                Book a Session
              </button>
            </Link>
          </motion.div>
        )}
      </AnimatePresence>

      <style>{`
        @media (max-width: 768px) {
          .desktop-nav { display: none !important; }
          .mobile-menu-btn { display: block !important; }
        }
      `}</style>
    </motion.nav>
  );
};

export default Navbar;
